-- Everything a NEW Supabase project needs, in one file: paste it into SQL Editor and press Run, once.
-- A project that is already running takes only the newer files in supabase/migrations instead.
-- Generated by "npm run db:bundle" from: 20261113000000_init.sql, 20261114000000_tighten.sql, 20261123000000_pages.sql, 20261124000000_enrollments.sql. Do not edit by hand.

-- ===================== 20261113000000_init.sql =====================

-- Assistant: tutoring-centre platform.
-- Who sees what is decided here, by row-level security, not by the screens:
--   admin   : everything
--   teacher : only the groups they teach, and only what their permissions allow
--   student : their own attendance, their own assignments and uploads; never grades or notes

-- ---------- tables ----------

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  role text not null check (role in ('admin', 'teacher', 'student')),
  full_name text not null check (length(trim(full_name)) between 2 and 80),
  phone text not null unique check (phone ~ '^01[0-9]{9}$'),
  subject text,                                   -- teacher
  group_id uuid,                                  -- student
  parent_phone text check (parent_phone ~ '^01[0-9]{9}$'),
  monthly_fee integer not null default 0 check (monthly_fee >= 0),
  can_attendance boolean not null default true,   -- teacher permissions
  can_grade boolean not null default true,
  can_add_students boolean not null default false,
  can_see_payments boolean not null default false,
  created_at timestamptz not null default now()
);

create table public.groups (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(trim(name)) between 2 and 80),
  teacher_id uuid not null references public.profiles (id),
  schedule text not null default '',
  created_at timestamptz not null default now()
);

alter table public.profiles
  add constraint profiles_group_fk foreign key (group_id) references public.groups (id);

create table public.assignments (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references public.groups (id) on delete cascade,
  title text not null check (length(trim(title)) between 2 and 120),
  questions integer not null check (questions between 1 and 200),
  created_by uuid not null default auth.uid() references public.profiles (id),
  created_at timestamptz not null default now()
);

create table public.attendance (
  group_id uuid not null references public.groups (id) on delete cascade,
  student_id uuid not null references public.profiles (id) on delete cascade,
  day date not null,
  status text not null check (status in ('present', 'late', 'absent')),
  recorded_by uuid not null default auth.uid() references public.profiles (id),
  recorded_at timestamptz not null default now(),
  primary key (group_id, student_id, day)
);

create table public.submissions (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references public.assignments (id) on delete cascade,
  student_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  photo_path text not null,
  status text not null default 'new' check (status in ('new', 'reviewed')),
  created_at timestamptz not null default now(),
  unique (assignment_id, student_id)
);

-- Kept apart from submissions so a student can read their submission's status and nothing else.
create table public.grades (
  submission_id uuid primary key references public.submissions (id) on delete cascade,
  correct integer not null check (correct >= 0),
  wrong integer not null check (wrong >= 0),
  note text not null default '' check (length(note) <= 2000),
  graded_by uuid not null default auth.uid() references public.profiles (id),
  graded_at timestamptz not null default now()
);

create table public.payments (
  student_id uuid not null references public.profiles (id) on delete cascade,
  month text not null check (month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  amount integer not null check (amount >= 0),
  recorded_by uuid not null default auth.uid() references public.profiles (id),
  paid_at timestamptz not null default now(),
  primary key (student_id, month)
);

create table public.notices (
  id uuid primary key default gen_random_uuid(),
  group_id uuid references public.groups (id) on delete cascade,  -- null = every group
  body text not null check (length(trim(body)) between 1 and 1000),
  created_by uuid not null default auth.uid() references public.profiles (id),
  created_at timestamptz not null default now()
);

create index on public.profiles (group_id);
create index on public.groups (teacher_id);
create index on public.assignments (group_id);
create index on public.attendance (student_id, day desc);
create index on public.submissions (student_id);
create index on public.submissions (status, created_at desc);

-- ---------- helpers (security definer so policies don't recurse through profiles) ----------

create function public.my_role() returns text
language sql stable security definer set search_path = public as $$
  select role from profiles where id = auth.uid()
$$;

create function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select role = 'admin' from profiles where id = auth.uid()), false)
$$;

create function public.my_group() returns uuid
language sql stable security definer set search_path = public as $$
  select group_id from profiles where id = auth.uid() and role = 'student'
$$;

create function public.teaches_group(g uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from groups where id = g and teacher_id = auth.uid())
$$;

create function public.teaches_student(s uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from profiles p join groups g on g.id = p.group_id
    where p.id = s and p.role = 'student' and g.teacher_id = auth.uid())
$$;

-- A teacher's permission flag; false for anyone who is not a teacher.
create function public.teacher_can(perm text) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select case perm
      when 'attendance' then can_attendance
      when 'grade' then can_grade
      when 'payments' then can_see_payments
      else false end
    from profiles where id = auth.uid() and role = 'teacher'), false)
$$;

create function public.submission_student(sub uuid) returns uuid
language sql stable security definer set search_path = public as $$
  select student_id from submissions where id = sub
$$;

revoke execute on all functions in schema public from public, anon;
grant execute on all functions in schema public to authenticated;

-- ---------- row-level security ----------

alter table public.profiles enable row level security;
alter table public.groups enable row level security;
alter table public.assignments enable row level security;
alter table public.attendance enable row level security;
alter table public.submissions enable row level security;
alter table public.grades enable row level security;
alter table public.payments enable row level security;
alter table public.notices enable row level security;

-- profiles: new accounts are made by the server (service role) after it checks the caller.
create policy profiles_read on public.profiles for select to authenticated
  using (id = auth.uid() or is_admin() or teaches_student(id));
create policy profiles_admin_update on public.profiles for update to authenticated
  using (is_admin()) with check (is_admin());

create policy groups_read on public.groups for select to authenticated
  using (is_admin() or teacher_id = auth.uid() or id = my_group());
create policy groups_admin_write on public.groups for all to authenticated
  using (is_admin()) with check (is_admin());

create policy assignments_read on public.assignments for select to authenticated
  using (is_admin() or teaches_group(group_id) or group_id = my_group());
create policy assignments_insert on public.assignments for insert to authenticated
  with check (is_admin() or teaches_group(group_id));
create policy assignments_delete on public.assignments for delete to authenticated
  using (is_admin() or teaches_group(group_id));

create policy attendance_read on public.attendance for select to authenticated
  using (is_admin() or teaches_group(group_id) or student_id = auth.uid());
create policy attendance_insert on public.attendance for insert to authenticated
  with check (is_admin() or (teaches_group(group_id) and teacher_can('attendance')));
create policy attendance_update on public.attendance for update to authenticated
  using (is_admin() or (teaches_group(group_id) and teacher_can('attendance')))
  with check (is_admin() or (teaches_group(group_id) and teacher_can('attendance')));

-- submissions: a student sends and may resend until it is reviewed; the teacher marks it reviewed.
create policy submissions_read on public.submissions for select to authenticated
  using (is_admin() or student_id = auth.uid() or teaches_student(student_id));
create policy submissions_student_insert on public.submissions for insert to authenticated
  with check (
    student_id = auth.uid() and status = 'new'
    and photo_path like auth.uid()::text || '/%'
    and exists (select 1 from assignments a where a.id = assignment_id and a.group_id = my_group()));
create policy submissions_student_resend on public.submissions for update to authenticated
  using (student_id = auth.uid() and status = 'new')
  with check (
    student_id = auth.uid() and status = 'new'
    and photo_path like auth.uid()::text || '/%'
    and exists (select 1 from assignments a where a.id = assignment_id and a.group_id = my_group()));
create policy submissions_review on public.submissions for update to authenticated
  using (is_admin() or (teaches_student(student_id) and teacher_can('grade')))
  with check (is_admin() or (teaches_student(student_id) and teacher_can('grade')));

-- grades: never readable by students.
create policy grades_read on public.grades for select to authenticated
  using (is_admin() or teaches_student(submission_student(submission_id)));
create policy grades_insert on public.grades for insert to authenticated
  with check (is_admin() or (teaches_student(submission_student(submission_id)) and teacher_can('grade')));
create policy grades_update on public.grades for update to authenticated
  using (is_admin() or (teaches_student(submission_student(submission_id)) and teacher_can('grade')))
  with check (is_admin() or (teaches_student(submission_student(submission_id)) and teacher_can('grade')));

create policy payments_read on public.payments for select to authenticated
  using (is_admin() or (teaches_student(student_id) and teacher_can('payments')));
create policy payments_admin_write on public.payments for all to authenticated
  using (is_admin()) with check (is_admin());

create policy notices_admin on public.notices for all to authenticated
  using (is_admin()) with check (is_admin());

-- ---------- photo storage ----------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('solutions', 'solutions', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

-- Paths are "<student id>/<assignment id>-<time>.jpg".
create policy solutions_student_upload on storage.objects for insert to authenticated
  with check (bucket_id = 'solutions' and my_role() = 'student'
    and (storage.foldername(name))[1] = auth.uid()::text);
create policy solutions_read on storage.objects for select to authenticated
  using (bucket_id = 'solutions' and (
    is_admin()
    or (storage.foldername(name))[1] = auth.uid()::text
    or exists (
      select 1 from profiles p join groups g on g.id = p.group_id
      where p.id::text = (storage.foldername(objects.name))[1] and g.teacher_id = auth.uid())));  -- objects.name: groups has a name too

-- ===================== 20261114000000_tighten.sql =====================

-- Tightening after the review of 14 Nov 2026.

-- One manager only, so two first-run forms sent at once cannot both make one.
create unique index one_admin on public.profiles ((true)) where role = 'admin';

-- Attendance: the student must be in the group the row is for.
drop policy attendance_insert on public.attendance;
drop policy attendance_update on public.attendance;
create policy attendance_insert on public.attendance for insert to authenticated
  with check (
    (is_admin() or (teaches_group(group_id) and teacher_can('attendance') and recorded_by = auth.uid()))
    and exists (select 1 from profiles p where p.id = student_id and p.group_id = attendance.group_id and p.role = 'student'));
create policy attendance_update on public.attendance for update to authenticated
  using (is_admin() or (teaches_group(group_id) and teacher_can('attendance')))
  with check (
    (is_admin() or (teaches_group(group_id) and teacher_can('attendance') and recorded_by = auth.uid()))
    and exists (select 1 from profiles p where p.id = student_id and p.group_id = attendance.group_id and p.role = 'student'));

-- Homework: a teacher writes it under their own name; only the manager deletes it (it takes the solutions and grades with it).
drop policy assignments_insert on public.assignments;
drop policy assignments_delete on public.assignments;
create policy assignments_insert on public.assignments for insert to authenticated
  with check (is_admin() or (teaches_group(group_id) and created_by = auth.uid()));
create policy assignments_delete on public.assignments for delete to authenticated
  using (is_admin());

-- Grades: a teacher grades under their own name.
drop policy grades_insert on public.grades;
drop policy grades_update on public.grades;
create policy grades_insert on public.grades for insert to authenticated
  with check (is_admin() or (teaches_student(submission_student(submission_id)) and teacher_can('grade') and graded_by = auth.uid()));
create policy grades_update on public.grades for update to authenticated
  using (is_admin() or (teaches_student(submission_student(submission_id)) and teacher_can('grade')))
  with check (is_admin() or (teaches_student(submission_student(submission_id)) and teacher_can('grade') and graded_by = auth.uid()));

-- A sent solution keeps its student and homework; only its student may change its photo. The teacher changes the status only.
create function public.submissions_fixed() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.student_id <> old.student_id or new.assignment_id <> old.assignment_id
     or (new.photo_path <> old.photo_path and old.student_id is distinct from auth.uid()) then
    raise exception 'only the status of a sent solution can change';
  end if;
  return new;
end $$;
revoke execute on function public.submissions_fixed() from public, anon;
create trigger submissions_fixed before update on public.submissions
  for each row execute function public.submissions_fixed();

-- ===================== 20261123000000_pages.sql =====================

-- A solution can be several pages: photo_path (one photo) becomes photo_paths (1 to 10 photos, in page order).

alter table public.submissions add column photo_paths text[];
update public.submissions set photo_paths = array[photo_path];

-- As before: a sent solution keeps its student and homework; only its student may change its pages.
create or replace function public.submissions_fixed() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.student_id <> old.student_id or new.assignment_id <> old.assignment_id
     or (new.photo_paths is distinct from old.photo_paths and old.student_id is distinct from auth.uid()) then
    raise exception 'only the status of a sent solution can change';
  end if;
  return new;
end $$;

-- The two policies that read photo_path go before the column does, and come back below.
drop policy submissions_student_insert on public.submissions;
drop policy submissions_student_resend on public.submissions;

alter table public.submissions
  drop column photo_path,
  alter column photo_paths set not null,
  add constraint submissions_pages
    check (cardinality(photo_paths) between 1 and 10 and array_position(photo_paths, null) is null);

-- Every page is "<student id>/<assignment id>-<anything>": in the student's own folder, and belonging
-- to this homework, so one solution can never point at the photos of another.
create function public.own_pages(paths text[], assignment uuid) returns boolean
language sql stable set search_path = public as $$
  select not exists (
    select 1 from unnest(paths) p
    where p is null or not starts_with(p, auth.uid()::text || '/' || assignment::text || '-'))
$$;
revoke execute on function public.own_pages(text[], uuid) from public, anon;
grant execute on function public.own_pages(text[], uuid) to authenticated;

create policy submissions_student_insert on public.submissions for insert to authenticated
  with check (
    student_id = auth.uid() and status = 'new'
    and own_pages(photo_paths, assignment_id)
    and exists (select 1 from assignments a where a.id = assignment_id and a.group_id = my_group()));
create policy submissions_student_resend on public.submissions for update to authenticated
  using (student_id = auth.uid() and status = 'new')
  with check (
    student_id = auth.uid() and status = 'new'
    and own_pages(photo_paths, assignment_id)
    and exists (select 1 from assignments a where a.id = assignment_id and a.group_id = my_group()));

-- ===================== 20261124000000_enrollments.sql =====================

-- A student can be in several groups (one per subject or teacher), each with its own monthly fee.
-- Until now a student had exactly one group, written on their profile.
--
--   enrollments        : who is in which group, and what they pay for it each month
--   payments           : now one per student, group and month
--   groups.archived_at : last year's groups are put away, not deleted, so their history stays
--   teachers           : see the homework, solutions and grades of their own groups only,
--                        not everything a shared student sends to other teachers
--   notices            : students and teachers can read the ones meant for their groups

-- ---------- enrollments ----------

create table public.enrollments (
  student_id uuid not null references public.profiles (id) on delete cascade,
  group_id uuid not null references public.groups (id) on delete cascade,
  monthly_fee integer not null default 0 check (monthly_fee >= 0),
  joined_at timestamptz not null default now(),
  primary key (student_id, group_id)
);
create index on public.enrollments (group_id);

insert into public.enrollments (student_id, group_id, monthly_fee, joined_at)
select id, group_id, monthly_fee, created_at from public.profiles
where role = 'student' and group_id is not null;

-- Only students are enrolled. Security definer, because the person adding may not be allowed to read that profile yet.
create function public.enrollments_students_only() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from profiles where id = new.student_id and role = 'student') then
    raise exception 'only a student can be put in a group';
  end if;
  return new;
end $$;
revoke execute on function public.enrollments_students_only() from public, anon;
create trigger enrollments_students_only before insert or update on public.enrollments
  for each row execute function public.enrollments_students_only();

-- ---------- payments: per group ----------

alter table public.payments add column group_id uuid references public.groups (id) on delete restrict;
update public.payments p set group_id = s.group_id from public.profiles s where s.id = p.student_id;
-- A payment of a student who was in no group cannot be placed; the app never made one.
delete from public.payments where group_id is null;
alter table public.payments
  drop constraint payments_pkey,
  alter column group_id set not null,
  add primary key (student_id, group_id, month);
create index on public.payments (month);

alter table public.groups add column archived_at timestamptz;

-- ---------- helpers ----------

create function public.in_group(g uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from enrollments where group_id = g and student_id = auth.uid())
$$;

-- A teacher "teaches" a student who is in at least one of their groups.
create or replace function public.teaches_student(s uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from enrollments e join groups g on g.id = e.group_id
    where e.student_id = s and g.teacher_id = auth.uid())
$$;

create function public.teaches_assignment(a uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from assignments w join groups g on g.id = w.group_id
    where w.id = a and g.teacher_id = auth.uid())
$$;

create function public.teaches_submission(sub uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from submissions s join assignments w on w.id = s.assignment_id join groups g on g.id = w.group_id
    where s.id = sub and g.teacher_id = auth.uid())
$$;

create or replace function public.teacher_can(perm text) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((
    select case perm
      when 'attendance' then can_attendance
      when 'grade' then can_grade
      when 'payments' then can_see_payments
      when 'add_students' then can_add_students
      else false end
    from profiles where id = auth.uid() and role = 'teacher'), false)
$$;

-- The app compares this with the version it was built for, and tells the manager which file to run when the database is behind.
create function public.schema_version() returns integer
language sql immutable as $$ select 4 $$;

revoke execute on function public.in_group(uuid), public.teaches_assignment(uuid), public.teaches_submission(uuid) from public, anon;
grant execute on function public.in_group(uuid), public.teaches_assignment(uuid), public.teaches_submission(uuid) to authenticated;
revoke execute on function public.schema_version() from public, anon;
grant execute on function public.schema_version() to authenticated, service_role;

-- ---------- row-level security ----------

alter table public.enrollments enable row level security;

create policy enrollments_read on public.enrollments for select to authenticated
  using (is_admin() or student_id = auth.uid() or teaches_group(group_id));
-- A teacher allowed to add students puts them in their own groups; fees and removals stay with the manager.
create policy enrollments_insert on public.enrollments for insert to authenticated
  with check (is_admin() or (teaches_group(group_id) and teacher_can('add_students')));
create policy enrollments_admin_update on public.enrollments for update to authenticated
  using (is_admin()) with check (is_admin());
create policy enrollments_admin_delete on public.enrollments for delete to authenticated
  using (is_admin());

drop policy groups_read on public.groups;
create policy groups_read on public.groups for select to authenticated
  using (is_admin() or teacher_id = auth.uid() or in_group(id));

drop policy assignments_read on public.assignments;
create policy assignments_read on public.assignments for select to authenticated
  using (is_admin() or teaches_group(group_id) or in_group(group_id));
-- Fixing a title or the number of questions.
create policy assignments_update on public.assignments for update to authenticated
  using (is_admin() or teaches_group(group_id))
  with check (is_admin() or teaches_group(group_id));

drop policy attendance_insert on public.attendance;
drop policy attendance_update on public.attendance;
create policy attendance_insert on public.attendance for insert to authenticated
  with check (
    (is_admin() or (teaches_group(group_id) and teacher_can('attendance') and recorded_by = auth.uid()))
    and exists (select 1 from enrollments e where e.student_id = attendance.student_id and e.group_id = attendance.group_id));
create policy attendance_update on public.attendance for update to authenticated
  using (is_admin() or (teaches_group(group_id) and teacher_can('attendance')))
  with check (
    (is_admin() or (teaches_group(group_id) and teacher_can('attendance') and recorded_by = auth.uid()))
    and exists (select 1 from enrollments e where e.student_id = attendance.student_id and e.group_id = attendance.group_id));
-- A class written on the wrong day can be taken back.
create policy attendance_delete on public.attendance for delete to authenticated
  using (is_admin() or (teaches_group(group_id) and teacher_can('attendance')));

drop policy submissions_read on public.submissions;
drop policy submissions_student_insert on public.submissions;
drop policy submissions_student_resend on public.submissions;
drop policy submissions_review on public.submissions;
create policy submissions_read on public.submissions for select to authenticated
  using (is_admin() or student_id = auth.uid() or teaches_assignment(assignment_id));
create policy submissions_student_insert on public.submissions for insert to authenticated
  with check (
    student_id = auth.uid() and status = 'new'
    and own_pages(photo_paths, assignment_id)
    and exists (select 1 from assignments a where a.id = assignment_id and in_group(a.group_id)));
create policy submissions_student_resend on public.submissions for update to authenticated
  using (student_id = auth.uid() and status = 'new')
  with check (
    student_id = auth.uid() and status = 'new'
    and own_pages(photo_paths, assignment_id)
    and exists (select 1 from assignments a where a.id = assignment_id and in_group(a.group_id)));
create policy submissions_review on public.submissions for update to authenticated
  using (is_admin() or (teaches_assignment(assignment_id) and teacher_can('grade')))
  with check (is_admin() or (teaches_assignment(assignment_id) and teacher_can('grade')));

drop policy grades_read on public.grades;
drop policy grades_insert on public.grades;
drop policy grades_update on public.grades;
create policy grades_read on public.grades for select to authenticated
  using (is_admin() or teaches_submission(submission_id));
create policy grades_insert on public.grades for insert to authenticated
  with check (is_admin() or (teaches_submission(submission_id) and teacher_can('grade') and graded_by = auth.uid()));
create policy grades_update on public.grades for update to authenticated
  using (is_admin() or (teaches_submission(submission_id) and teacher_can('grade')))
  with check (is_admin() or (teaches_submission(submission_id) and teacher_can('grade') and graded_by = auth.uid()));

drop policy payments_read on public.payments;
create policy payments_read on public.payments for select to authenticated
  using (is_admin() or (teaches_group(group_id) and teacher_can('payments')));

create policy notices_read on public.notices for select to authenticated
  using (group_id is null or in_group(group_id) or teaches_group(group_id));

-- Photos: a teacher opens the pages of homework they set. A page is "<student id>/<assignment id>-<anything>".
drop policy solutions_read on storage.objects;
create policy solutions_read on storage.objects for select to authenticated
  using (bucket_id = 'solutions' and (
    is_admin()
    or (storage.foldername(name))[1] = auth.uid()::text
    or exists (
      select 1 from assignments w join groups g on g.id = w.group_id
      where w.id::text = left(storage.filename(objects.name), 36) and g.teacher_id = auth.uid())));

-- ---------- the old one-group columns go ----------

drop function public.my_group();
drop function public.submission_student(uuid);
alter table public.profiles drop column group_id, drop column monthly_fee;
